cd ~/captures; python3 -c "
from PIL import Image
def blobs(f):
    im=Image.open(f).convert('L'); w,h=im.size; px=im.load()
    seen=set(); out=[]
    for y in range(h):
        for x in range(w):
            if px[x,y]<80 and (x,y) not in seen:
                st=[(x,y)]; seen.add((x,y)); pts=[]
                while st:
                    cx,cy=st.pop(); pts.append((cx,cy))
                    for nx,ny in ((cx+1,cy),(cx-1,cy),(cx,cy+1),(cx,cy-1)):
                        if 0<=nx<w and 0<=ny<h and (nx,ny) not in seen and px[nx,ny]<80:
                            seen.add((nx,ny)); st.append((nx,ny))
                if 30<len(pts)<5000:
                    out.append((len(pts), round(sum(p[0] for p in pts)/len(pts),1), round(sum(p[1] for p in pts)/len(pts),1), min(p[1] for p in pts), max(p[1] for p in pts)))
    print(f,out)
for f in ['wrist_004.png','wrist_005.png','wrist_006.png','wrist_007.png']: blobs(f)
"

